import React, { useContext } from 'react';

import { useNavigate } from 'react-router-dom';

import { getEquipSets } from '@apps/Hiking/@services/equip.service';
import { IEquipSetListItem } from '@apps/Hiking/@types/equip.types';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';

import { editEquipSetParams } from '../components/EquipSetEditParams';
import EquipSetListItem from '../components/EquipSetListItem';

const EquipPageSets: React.FC = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IEquipSetListItem[]>([]);

  const navigate = useNavigate();
  const authContext = useContext(AuthContext);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getEquipSets();
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/equip', text: 'Снаряжение' },
          { href: '/equip/sets', text: 'Сборки', active: true },
        ]}
      />

      <PohContainer>
        <PageHeader title="Сборки">
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={async () => {
              if (!authContext.user?.id) return;
              const added = await editEquipSetParams({
                id: 0,
                description: '',
                name: '',
                backpack: null,
                hiking: null,
                date_update: new Date(),
              });
              notificationHelper.success('Добавлено');

              setData((cur) => (!authContext.user?.id ? [] : [...cur, added]));
            }}
          >
            Добавить
          </PohButton>
        </PageHeader>
        <p className="mt-n3">
          <small>
            Здесь можно создавать списки вещей, для того, чтобы грамотно собрать рюкзак в поход и
            ничего не забыть.
          </small>
        </p>
        {data.length === 0 && <Empty>Пока тут пусто...</Empty>}
        {data.length > 0 && (
          <PohList
            data={data.map((item) => {
              return {
                key: item.id,
                children: <EquipSetListItem item={item} />,
                action: true,
                onClick: () => navigate(`/equip/sets/${item.id}`),
              };
            })}
          />
        )}
      </PohContainer>
    </div>
  );
};

export default EquipPageSets;
